import { Placard } from 'snice/react';
export function App() {
  return <Placard>Hi</Placard>;
}

import { Placard as Meta } from 'snice/react';
export function App() {
  return <Meta />;
}

import type { ButtonProps } from 'snice/react';
export function App() {
  return <ButtonProps />;
}

import { Button } from 'snice/react';
export function App() {
  return <Button variant="primary">Save</Button>;
}

import { SniceRouter, Route } from 'snice/react';
import { Home } from './Home';
export function App() {
  return <SniceRouter mode="hash"><Route path="/" page={Home} /></SniceRouter>;
}

import type { UseRequestRouteMap, UseRequestHandlerOptions } from 'snice/react';
export const routes: UseRequestRouteMap = {};
export const options: UseRequestHandlerOptions = {};

import { useRef } from 'react';
import type { SniceComponentRef, SniceFormRef } from 'snice/react';
export function useRefs() {
  const modal = useRef<SniceComponentRef>(null);
  const input = useRef<SniceFormRef | null>(null);
  return { modal, input };
}

import type { Placard } from 'snice/react';
export const byRoute: Map<string, Placard> = new Map();
export type PlacardList = Array<Placard>;
export type Nullable = Promise<Placard | null>;
